#!/usr/bin/env node
// Generates src/theme/tokens.ts from design/tokens.json, the token file exported
// from the Backseat Mom design system artifact. Run `npm run tokens` after
// replacing design/tokens.json; CI fails if the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const src = JSON.parse(readFileSync(join(root, 'design/tokens.json'), 'utf8'));
const out = join(root, 'src/theme/tokens.ts');

const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const px = (v) => Number(String(v).replace('px', ''));

const colors = { light: {}, dark: {} };
for (const t of src.color.tokens) {
  colors.light[camel(t.name)] = t.value.light;
  colors.dark[camel(t.name)] = t.value.dark;
}

const space = {};
for (const t of src.spacing.tokens) space[t.name.replace('space-', '')] = px(t.value);

const radius = {};
for (const t of src.radius.tokens) radius[t.name.replace('radius-', '')] = px(t.value);

// CSS box-shadow "0 6px 20px rgba(r, g, b, a)" -> React Native shadow props.
function shadow(css) {
  const m = css.match(/^(\S+)\s+(\S+)\s+(\S+)\s+rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)$/);
  if (!m) throw new Error(`Unsupported shadow: ${css}`);
  const [, x, y, blur, r, g, b, a] = m;
  return {
    shadowColor: `rgb(${r}, ${g}, ${b})`,
    shadowOffset: { width: px(x), height: px(y) },
    shadowOpacity: Number(a),
    shadowRadius: px(blur) / 2,
    elevation: Math.round(px(blur) / 3),
  };
}
const shadows = { light: {}, dark: {} };
for (const t of src.shadow.tokens) {
  const name = camel(t.name.replace('shadow-', ''));
  shadows.light[name] = shadow(t.value.light);
  shadows.dark[name] = shadow(t.value.dark);
}

const type = {};
for (const group of src.type.groups) {
  for (const s of group.styles) {
    type[s.name] = {
      family: group.family,
      fontSize: px(s.fontSize),
      lineHeight: px(s.lineHeight),
      fontWeight: s.fontWeight,
    };
  }
}

const body = `// Generated by scripts/generate-theme.mjs from design/tokens.json. Do not edit.
// Source: ${src.name} design system, tokens version ${src.version}.

export const colors = ${JSON.stringify(colors, null, 2)} as const;

export const space = ${JSON.stringify(space, null, 2)} as const;

export const radius = ${JSON.stringify(radius, null, 2)} as const;

export const shadows = ${JSON.stringify(shadows, null, 2)} as const;

export const typeScale = ${JSON.stringify(type, null, 2)} as const;
`;

if (process.argv.includes('--check')) {
  const current = readFileSync(out, 'utf8');
  if (current !== body) {
    console.error('src/theme/tokens.ts is out of date. Run `npm run tokens`.');
    process.exit(1);
  }
  console.log('Theme tokens are up to date.');
} else {
  writeFileSync(out, body);
  console.log(`Wrote ${out}`);
}
